//refAssemblies: TCAdmin.SDK.dll, TCAdmin.GameHosting.SDK.dll, TCAdmin.Scripting.dll, TCAdmin.Monitor.dll
using System;
using System.Diagnostics;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Net.Http;
using System.Threading.Tasks;
using TCAdmin.SDK.Misc.Extensions;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

void WriteLog(string s, int? progress = null, bool rewriteLastLog = false)
{
    if(Globals.ThisTaskStepHandler != null)
    {
        Globals.ThisTaskStepHandler.UpdateProgress(progress: progress, log: s);
    }
    else if(Globals.ThisTaskStep!=null)
    {
        if(progress.HasValue)
        {
            Globals.ThisTaskStep.Progress = progress.Value;
        }

        if(rewriteLastLog)
        {
            Globals.ThisTaskStep.DisplayLog = s;
            Globals.ThisTaskStep.DisplayDebugLog = s;
        }
        else
        {
            Globals.ThisTaskStep.AddDebugLog(s, skipDuplicates:true);
        }
        Globals.TCATaskManager.Update(Globals.ThisTask, true);
    }
    else
    {
        Globals.ScriptConsole.WriteLine(s);
    }
}

// Runs a helper the monitor needs but the SDK does not wrap; the exit code is the only success signal.
void Run(string fileName, params string[] arguments)
{
    using var p = new Process();
    p.StartInfo.FileName = fileName;
    foreach(var argument in arguments)
    {
        p.StartInfo.ArgumentList.Add(argument);
    }
    p.StartInfo.UseShellExecute = false;
    p.StartInfo.RedirectStandardError = true;
    p.StartInfo.RedirectStandardOutput = true;
    p.Start();

    var errorTask = p.StandardError.ReadToEndAsync();
    p.StandardOutput.ReadToEnd();
    p.WaitForExit();
    var error = errorTask.GetAwaiter().GetResult();

    if(p.ExitCode != 0)
    {
        throw new Exception($"\"{fileName}\" failed with exit code {p.ExitCode}: {error}");
    }
}

// TCAdmin's game-file copy skips symbolic links, so the musl loader would lose every soname
// link (libstdc++.so.6 -> libstdc++.so.6.0.33) and FXServer would not start. Replacing the
// links under these three folders with real files costs ~15 MB; the busybox applet links under
// alpine/{bin,sbin,usr/bin,usr/sbin} are left alone because FXServer never uses them and
// materialising those would cost ~600 MB.
void MaterializeSymlinks(string root)
{
    const string script =
        "set -e; cd \"$1\"; for d in alpine/lib alpine/usr/lib alpine/etc; do " +
        "[ -d \"$d\" ] || continue; " +
        "find \"$d\" -type l | while IFS= read -r l; do " +
        "t=$(readlink -f \"$l\") || continue; [ -f \"$t\" ] || continue; " +
        "cp --remove-destination -p \"$t\" \"$l\"; done; done";

    Run("/bin/sh", "-c", script, "sh", root);
}

void MakeExecutable(string root)
{
    var mode = UnixFileMode.UserRead | UnixFileMode.UserWrite | UnixFileMode.UserExecute |
               UnixFileMode.GroupRead | UnixFileMode.GroupExecute |
               UnixFileMode.OtherRead | UnixFileMode.OtherExecute;

    var relativePaths = new[]
    {
        "run.sh",
        Path.Combine("alpine", "opt", "cfx-server", "run.sh"),
        Path.Combine("alpine", "opt", "cfx-server", "FXServer"),
        Path.Combine("alpine", "opt", "cfx-server", "ld-musl-x86_64.so.1"),
        Path.Combine("alpine", "lib", "ld-musl-x86_64.so.1")
    };

    foreach(var relativePath in relativePaths)
    {
        var fullPath = Path.Combine(root, relativePath);
        if(File.Exists(fullPath))
        {
            File.SetUnixFileMode(fullPath, mode);
        }
    }
}

var gameFilesPath = Globals.ThisServer.Configuration.GameFilesPath;
var fiveMPath = Path.Combine(gameFilesPath, Globals.ThisGame.FileAndDirectoryConfig.AutoSetupFolderName);
var downloadedFile = Path.Combine(gameFilesPath, "__fivem-linux.tar.xz");
var serverDataZip = Path.Combine(gameFilesPath, "__cfx-server-data.zip");
var serverDataTemp = Path.Combine(gameFilesPath, "__cfx-server-data-temp");
var serverDataPath = Path.Combine(fiveMPath, "server-data");

Directory.CreateDirectory(gameFilesPath);
Directory.CreateDirectory(fiveMPath);

try
{
    // A top-level "using var" is rejected by the Roslyn scripting host; the block form is required.
    using (var httpClient = new HttpClient())
    {
        httpClient.Timeout = TimeSpan.FromMinutes(30); // The artifact is ~70 MB; the 100s default aborts it.

        try
        {
            WriteLog("Downloading the latest FiveM Linux artifact...", 5);
            await httpClient.DownloadFile("http://downloads.tcadmin.net/games/fivem-linux.aspx", downloadedFile, Globals.ThisCancellationToken);

            WriteLog("Extracting the FiveM Linux artifact...", 35);
            Run("tar", "-xf", downloadedFile, "-C", fiveMPath); // The tarball has no wrapping folder.

            WriteLog("Restoring symbolic links...", 45);
            MaterializeSymlinks(fiveMPath);
        }
        finally
        {
            if(File.Exists(downloadedFile))
            {
                File.Delete(downloadedFile);
            }
        }

        try
        {
            WriteLog("Downloading the cfx-server-data files...", 55);
            await httpClient.DownloadFile("https://github.com/citizenfx/cfx-server-data/archive/refs/heads/master.zip", serverDataZip, Globals.ThisCancellationToken);

            WriteLog("Extracting the cfx-server-data files...", 70);
            if(Directory.Exists(serverDataTemp))
            {
                Directory.Delete(serverDataTemp, true);
            }
            Directory.CreateDirectory(serverDataTemp);
            ZipFile.ExtractToDirectory(serverDataZip, serverDataTemp);

            var extractedFolder = Path.Combine(serverDataTemp, "cfx-server-data-master");
            if(!Directory.Exists(extractedFolder))
            {
                extractedFolder = Directory.GetDirectories(serverDataTemp).FirstOrDefault();
            }

            if(string.IsNullOrEmpty(extractedFolder) || !Directory.Exists(extractedFolder))
            {
                throw new Exception("The cfx-server-data archive did not contain the expected folder.");
            }

            // Re-runnable: the previous server-data goes before the rename.
            if(Directory.Exists(serverDataPath))
            {
                Directory.Delete(serverDataPath, true);
            }
            Directory.Move(extractedFolder, serverDataPath);
        }
        finally
        {
            if(File.Exists(serverDataZip))
            {
                File.Delete(serverDataZip);
            }

            if(Directory.Exists(serverDataTemp))
            {
                Directory.Delete(serverDataTemp, true);
            }
        }
    }

    WriteLog("Setting executable permissions...", 90);
    MakeExecutable(fiveMPath);

    // run.sh execs the musl loader, so it must exist or the service never starts.
    var runScript = Path.Combine(fiveMPath, "run.sh");
    if(!File.Exists(runScript))
    {
        throw new Exception($"\"{runScript}\" was not found after extracting the FiveM Linux artifact.");
    }

    var resourcesPath = Path.Combine(serverDataPath, "resources");
    if(!Directory.Exists(resourcesPath))
    {
        throw new Exception($"\"{resourcesPath}\" was not found after extracting the cfx-server-data files.");
    }

    WriteLog("FiveM Linux game files are ready.", 100);
}
catch(Exception ex)
{
    WriteLog($"Failed to download the FiveM Linux game files: {ex.Message}");
    throw;
}
